263: function petshop_vf_sync_stock( $mode, $limit, $offset, $only_sku ) {
264: 
265: 	if ( ! class_exists( 'Petshop_Fulfillment' ) ) {
266: 		return array( 'error' => 'Petshop_Fulfillment klasė nerasta' );
267: 	}
268: 
269: 	$loaded = petshop_vf_sync_load_feed();
270: 	if ( isset( $loaded['error'] ) ) return $loaded;
271: 	$feed = $loaded['feed'];
272: 
273: 	global $wpdb;
274: 
275: 	$where_only = '';
276: 	if ( ! empty( $only_sku ) ) {
277: 		$in = "'" . implode( "','", array_map( 'esc_sql', $only_sku ) ) . "'";
278: 		$where_only = " AND meta_value IN ($in)";
279: 	}
280: 	$pids = $wpdb->get_col( $wpdb->prepare(
281: 		"SELECT DISTINCT post_id FROM {$wpdb->postmeta}
282: 		 WHERE meta_key='_vf_supplier_sku' AND meta_value != '' $where_only
283: 		 ORDER BY post_id ASC LIMIT %d OFFSET %d",
284: 		$limit, $offset
285: 	) );
286: 
287: 	$stats = array(
288: 		'path'             => 'stock',
289: 		'mode'             => $mode,
290: 		'now'              => current_time( 'mysql' ),
291: 		'cache_mtime'      => $loaded['cache_mtime'],
292: 		'cache_age_h'      => $loaded['cache_age_h'],
293: 		'feed_items'       => count( $feed ),
294: 		'products_scanned' => 0,
295: 		'skip_no_feed'     => 0,  // -> zero out'inam qty
296: 		'would_zero_out'   => 0,  // iškritusios iš feed -> qty=0
297: 		'would_change_qty' => 0,  // qty pasikeis
298: 		'would_refresh_only' => 0, // qty tas pats, tik sync stamp'as
299: 		'applied'          => 0,
300: 	);
301: 	$examples = array();
302: 	$fulfillment = new Petshop_Fulfillment();
303: 
304: 	foreach ( $pids as $pid ) {
305: 		$stats['products_scanned']++;
306: 		$sku = (string) get_post_meta( $pid, '_vf_supplier_sku', true );
307: 		$old_qty = (int) get_post_meta( $pid, '_vf_qty', true );
308: 
309: 		if ( ! isset( $feed[ $sku ] ) ) {
310: 			// Iškritusi iš feed'o -> zero out (kad "užšąlusi" instock nebeklaidintų)
311: 			$stats['skip_no_feed']++;
312: 			$new_qty = 0;
313: 			$reason  = 'DROPPED_FROM_FEED';
314: 		} else {
315: 			$new_qty = (int) $feed[ $sku ]['qty'];
316: 			$reason  = ( $new_qty === $old_qty ) ? 'REFRESH_STAMP_ONLY' : 'CHANGE_QTY';
317: 		}
318: 
319: 		if ( $reason === 'DROPPED_FROM_FEED' && $old_qty !== 0 ) $stats['would_zero_out']++;
320: 		if ( $reason === 'CHANGE_QTY' ) $stats['would_change_qty']++;
321: 		if ( $reason === 'REFRESH_STAMP_ONLY' ) $stats['would_refresh_only']++;
322: 
323: 		if ( count( $examples ) < 20 && $reason !== 'REFRESH_STAMP_ONLY' ) {
324: 			$examples[] = array(
325: 				'pid'    => $pid,
326: 				'sku'    => $sku,
327: 				'title'  => mb_substr( get_the_title( $pid ), 0, 45 ),
328: 				'old_qty'=> $old_qty,
329: 				'new_qty'=> $new_qty,
330: 				'reason' => $reason,
331: 			);
332: 		}
333: 
334: 		if ( $mode === 'apply' ) {
335: 			update_post_meta( $pid, '_vf_qty', $new_qty );
336: 			update_post_meta( $pid, '_vf_last_sync', current_time( 'mysql' ) );
337: 			$fulfillment->update_vf_qty( $pid, $new_qty );
338: 			$stats['applied']++;
339: 		}
340: 	}
341: 
342: 	return array( 'stats' => $stats, 'examples' => $examples );
343: }
