556: add_action( 'petshop_vf_sync_stock_hourly', function() {
557: 	$offset = 0; $total_applied = 0; $safe = 20;
558: 	while ( $safe-- > 0 ) {
559: 		$r = petshop_vf_sync_stock( 'apply', 200, $offset, array() );
560: 		if ( isset( $r['error'] ) ) { error_log( '[VF Stock Cron] ' . $r['error'] ); break; }
561: 		$scanned = (int) ( $r['stats']['products_scanned'] ?? 0 );
562: 		$total_applied += (int) ( $r['stats']['applied'] ?? 0 );
563: 		if ( $scanned < 200 ) break;
564: 		$offset += 200;
565: 	}
566: 	update_option( 'petshop_vf_stock_last_run', array(
567: 		'when' => current_time( 'mysql' ), 'applied' => $total_applied,
568: 	) );
569: } );
